Translate("esES", "hall-of-thanes", {
	title = "Hall of Thanes",
	aliases = { "The Hall of Thanes" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Hall of Thanes se encuentra en las cavernas bajo {link:old-ironforge}Old Ironforge{/link}, muy por debajo del {link:high-seat}High Seat{/link}. Es un lugar de tumbas y cámaras, donde reposan los grandes enanos del pasado de {link:ironforge}Forjaz{/link} y donde se sellaron los tesoros de sus reyes. Durante generaciones, solo sus guardianes lo recorrieron. Ahora los muertos están inquietos, y los {link:dark-iron-dwarves}Hierro Negro{/link} han irrumpido desde abajo.]=],
		},
		{
			title = "Orígenes",
			text = [=[Ninguna crónica registra cuándo se dio sepultura al primer thane en estas salas. Las cámaras de su punto más profundo se llaman el Reliquary of Kings. Entre las reliquias que se guardaban allí había una tablilla de piedra de los días posteriores a la guerra de los tres clanes, cuando Madoran se convirtió en el primer rey Barbabronce de {link:ironforge}Forjaz{/link}: el tratado de paz entre los Barbabronce y los Martillo Salvaje, que los {link:dark-iron-dwarves}Hierro Negro{/link} se negaron a firmar. Otra cámara, Anvilmar's Rest, alberga la tumba de un thane llamado {link:faldrim-anvilmar}Faldrim Anvilmar{/link}.]=],
		},
		{
			title = "La incursión",
			text = [=[El vidente de la tierra {link:earthseer-farsen}Farsen{/link}, un Martillo Salvaje de visita en {link:dun-morogh}Dun Morogh{/link}, fue el primero en ver el peligro. Espías {link:dark-iron-dwarves}Hierro Negro{/link} habían entrado en la región, y un mapa arrebatado a sus muertos mostraba túneles que convergían bajo {link:ironforge}Forjaz{/link}. Los Hierro Negro subieron a las cámaras en máquinas topo. Sus saqueadores empezaron a despojar las tumbas de sus reliquias familiares, sus ingenieros lanzaron bombas y sus invocadores llamaron al fuego. Gólems de piedra caminan a su lado. Al mismo tiempo, los espíritus de los muertos despertaron, furiosos y atormentados, y empezaron a rondar sus propias salas.]=],
		},
		{
			title = "Jefes",
			text = [=[• {b}{link:faldrim-anvilmar}Faldrim Anvilmar{/link}{/b}, un thane de antaño cuyo espíritu no puede descansar, consumido por un antiguo rencor.
• {b}{link:magmatus}Magmatus{/link}{/b}, una criatura de fuego vivo que lucha junto a un invocador {link:dark-iron-dwarves}Hierro Negro{/link}.
• {b}Plunder{/b}, un elemental que recorre una sala de las cámaras y arroja a los intrusos a un lado.
• {b}{link:durgen-dirgehammer}Durgen Dirgehammer{/link}{/b}, el comandante de la incursión Hierro Negro, protegido por gólems en las cámaras inferiores.]=],
		},
		{
			title = "En el presente",
			text = [=[Los guardianes de las tumbas no bajarán al Hall hasta que los muertos se calmen. Un {link:gnomes}gnomo{/link} que afirma que patrullaba las cámaras quiere que se suban de nuevo las reliquias familiares, y dice que las catalogará. El vidente de la tierra {link:earthseer-farsen}Farsen{/link} pide voluntarios que bajen, encuentren al comandante {link:dark-iron-dwarves}Hierro Negro{/link} y lleven su cabeza al rey. El rey {link:magni-bronzebeard}Magni Bronzebeard{/link} ha prometido que, una vez expulsados los invasores, las brechas se sellarán y las salas inferiores se reforzarán, para que ningún enemigo pueda volver a entrar por allí.]=],
		},
	},
})

Translate("esES", "faldrim-anvilmar", {
	title = "Faldrim Anvilmar",
	subtitle = "El thane sin descanso",
	found = "Anvilmar's Rest, en el Hall of Thanes",
	allegiance = "Los muertos de Forjaz",
	aliases = { "Faldrim" },
	sections = {
		{
			title = "Resumen",
			text = [=[Faldrim Anvilmar fue un thane de {link:ironforge}Forjaz{/link}, sepultado en la cámara llamada Anvilmar's Rest. Cuando los {link:dark-iron-dwarves}Hierro Negro{/link} irrumpieron en las cámaras, su espíritu despertó con los demás, y no despertó en paz. Recorre su sala consumido por un antiguo rencor, golpeando la mente de los vivos y lanzando una maldición sobre quienes se le oponen. El fantasma de alguien que le sirvió suplica que alguien deje por fin descansar a su thane.]=],
		},
		{
			title = "Sin registro",
			text = [=[Faldrim lleva el nombre de Anvilmar, el nombre del gran rey bajo el que todos los enanos estuvieron unidos una vez. Qué lo unía a aquel rey, y qué rencor lo retiene ahora, ninguna crónica lo dice.]=],
		},
	},
	mentions = {
		{ text = "Un antiguo rencor" },
	},
	bonds = {
		{ id = "durgen-dirgehammer", name = "Durgen Dirgehammer", note = "el invasor de su tumba" },
	},
})

Translate("esES", "magmatus", {
	title = "Magmatus",
	subtitle = "Fuego de los Hierro Negro",
	found = "El Hall of Thanes",
	allegiance = "Enanos Hierro Negro",
	sections = {
		{
			title = "Resumen",
			text = [=[Magmatus es una criatura de fuego vivo que ha llegado al {link:hall-of-thanes}Hall of Thanes{/link} con los {link:dark-iron-dwarves}Hierro Negro{/link}. Un invocador Hierro Negro permanece a su lado, y las llamas que brotan de ella envuelven a todos los que están cerca. Los Hierro Negro sirven a los señores del fuego desde la caída de su ciudad de {link:ruins-of-thaurissan}Thaurissan{/link}, y sus invocadores llevan el fuego consigo allá donde van. En las tumbas de los thanes, entre la vieja piedra de {link:ironforge}Forjaz{/link}, Magmatus arde como una señal de quién ha llegado.]=],
		},
		{
			title = "Importancia",
			text = [=[Magmatus demuestra que la incursión {link:dark-iron-dwarves}Hierro Negro{/link} no es una simple banda de ladrones. Quienes llegaron bajo {link:ironforge}Forjaz{/link} trajeron consigo el poder de sus amos.]=],
		},
	},
})

Translate("esES", "plunder", {
	title = "Plunder",
	subtitle = "Guardián de las cámaras",
	found = "Una sala de las cámaras, en el Hall of Thanes",
	allegiance = "Desconocida",
	sections = {
		{
			title = "Resumen",
			text = [=[Plunder es un ser elemental que recorre una de las largas salas del {link:hall-of-thanes}Hall of Thanes{/link}. Golpea con tanta fuerza que quienes reciben sus golpes salen despedidos a través de la cámara. Los guardianes de la sala no han dicho si sirve a los {link:dark-iron-dwarves}Hierro Negro{/link}, si guarda las cámaras de los reyes o si simplemente entró desde los lugares profundos a través de las brechas.]=],
		},
		{
			title = "Sin registro",
			text = [=[Nada se ha escrito sobre el origen de Plunder ni sobre a quién obedece. Su nombre es todo lo que se sabe, y encaja bastante bien con los asuntos de los {link:dark-iron-dwarves}Hierro Negro{/link} en las cámaras.]=],
		},
	},
})

